package com.coffeeshop.repository;import com.coffeeshop.dto.SettingCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.SettingModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;public final class JdbcSettingRepository implements SettingRepository{private final DataSource ds;public JdbcSettingRepository(DataSource d){ds=Objects.requireNonNull(d);}public List<SettingModels.Setting>find(String search){String q="SELECT s.setting_id,s.setting_key,s.setting_value,s.value_type,s.description,u.username,s.updated_at,s.row_version FROM dbo.settings s LEFT JOIN dbo.users u ON u.user_id=s.updated_by_user_id WHERE (?='' OR s.setting_key LIKE ? OR COALESCE(s.description,'') LIKE ?) ORDER BY s.setting_key";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(q)){String x=search==null?"":search.trim(),like="%"+x+"%";s.setString(1,x);s.setString(2,like);s.setString(3,like);try(ResultSet r=s.executeQuery()){List<SettingModels.Setting>out=new ArrayList<>();while(r.next())out.add(new SettingModels.Setting(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getTimestamp(7).toLocalDateTime(),r.getBytes(8)));return List.copyOf(out);}}catch(SQLException e){throw fail("Unable to load settings.",e);}}public long save(SettingCommands.Save q,long user){try(Connection c=ds.getConnection()){c.setAutoCommit(false);try{long id;String before=null;if(q.id()!=null)try(PreparedStatement s=c.prepareStatement("SELECT setting_value FROM dbo.settings WITH(UPDLOCK,HOLDLOCK) WHERE setting_id=?")){s.setLong(1,q.id());try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalStateException("Setting no longer exists.");before=r.getString(1);}}if(q.id()==null){try(PreparedStatement s=c.prepareStatement("INSERT dbo.settings(setting_key,setting_value,value_type,description,updated_by_user_id) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){params(s,q);s.setLong(5,user);s.executeUpdate();id=key(s);}}else{id=q.id();try(PreparedStatement s=c.prepareStatement("UPDATE dbo.settings SET setting_key=?,setting_value=?,value_type=?,description=?,updated_by_user_id=?,updated_at=SYSUTCDATETIME() WHERE setting_id=? AND row_version=?")){params(s,q);s.setLong(5,user);s.setLong(6,id);s.setBytes(7,q.version());one(s.executeUpdate());}}try(PreparedStatement s=c.prepareStatement("INSERT dbo.audit_logs(user_id,action_code,entity_type,entity_id,before_data,after_data,details) VALUES(?,'SETTING_SAVED','SETTING',?,?,?,?)")){s.setLong(1,user);s.setLong(2,id);nullable(s,3,before);s.setString(4,q.value());s.setString(5,"Setting "+q.key()+" saved");s.executeUpdate();}c.commit();return id;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to save setting. Check that its key is unique.",e);}}private static void params(PreparedStatement s,SettingCommands.Save q)throws SQLException{s.setString(1,q.key());s.setString(2,q.value());s.setString(3,q.type());nullable(s,4,q.description());}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static void one(int n){if(n!=1)throw new IllegalStateException("Setting changed. Refresh and try again.");}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated key unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
